import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {9, 4, 7, 1, 8, 2};
        for (int i = 1; i < a.length; i++) {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
        }
        System.out.println(Arrays.toString(a));
    }
}
